#!/usr/bin/env bash
# Shared settings for the Kamal demo scripts. Sourced, not executed.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
OUTPUT="$ROOT/deploy/output/kamal"
VM_NAME="${VM_NAME:-kamal-demo}"
REGISTRY_PORT="${REGISTRY_PORT:-5001}"
SSH_KEY="$HOME/.ssh/kamal-multipass"
KAMAL="$(command -v kamal 2>/dev/null || echo /opt/homebrew/lib/ruby/gems/4.0.0/bin/kamal)"

# Apps generated by Vensas.Aspire.Hosting.Kamal — the first one owns the accessories
APPS=(server frontend cookie-sensor)

VM_IP="$(multipass info "$VM_NAME" 2>/dev/null | awk '/IPv4/ { print $2 }')"
# Host IP on the Multipass bridge: last octet → 1 (e.g. 192.168.64.5 → 192.168.64.1)
HOST_IP="${VM_IP%.*}.1"
REGISTRY_HOST="$HOST_IP:$REGISTRY_PORT"

# .kamal/secrets only references env vars — demo defaults, override as needed
export POSTGRES_PASSWORD="${POSTGRES_PASSWORD:-cookiejar}"
export RABBITMQ_PASSWORD="${RABBITMQ_PASSWORD:-cookiejar}"
export KAMAL_REGISTRY_PASSWORD="${KAMAL_REGISTRY_PASSWORD:-unused}"

# Kamal uses the ssh-agent; the generated deploy.yml only sets the user
ssh-add -q "$SSH_KEY" 2>/dev/null || true

config_for() {
  if [[ "$1" == "${APPS[0]}" ]]; then echo "config/deploy.yml"; else echo "config/deploy.$1.yml"; fi
}

require_output() {
  if [[ ! -f "$OUTPUT/config/deploy.yml" ]]; then
    echo "No Kamal output found at $OUTPUT — run 2-publish.sh first." >&2
    exit 1
  fi
}
